extern void compare_LED2(void);

void translate_test(void) {
	int8_t i = 1;
	int8_t j = 0;
	int8_t k = -1;

	int8_t a = -12;
	int8_t b = -2;

	while (i > j) {
		i = i + a - (2 * j);

		if (j >= k) {
			i = i + 2;
			k = k - b + (2 * j);
		}

		j++;
	}
}

// Test cases for translate:
